 if(cards.has(c.name)){p.body=`Here you go, ${cards.get(c.name)}! Here's our ${c.city} digital card to save and share whenever a client needs a moving quote. You're welcome to call this number too. - John`;p.media_urls=[await asset(c.city)];}
